#!/usr/bin/env python3
"""Wrap packaged config and evaluator as one injectable extension-owned function."""

import sys
from pathlib import Path
from textwrap import indent


def bundle_rules(config, evaluator, output):
    source = config.read_text()
    engine = evaluator.read_text()
    output.write_text(
        "// Generated by scripts/bundle_rules.py. Edit default-rules.js instead.\n"
        "/* exported defaultRules */\n"
        "function defaultRules(ruleId) {\n"
        + indent(source, "  ")
        + "\n"
        + indent(engine, "  ")
        + "\n  return evaluateRules(RULES, ruleId);\n}\n"
    )


if __name__ == "__main__":
    root = Path(__file__).resolve().parent.parent
    config = Path(sys.argv[1]) if len(sys.argv) > 1 else root / "extension/default-rules.js"
    output = Path(sys.argv[2]) if len(sys.argv) > 2 else root / "extension/bundled-rules.js"
    bundle_rules(config, root / "extension/rule-evaluator.js", output)
